import{_ as i,H as p,f as a,i as e}from"./chunks/framework.BH2BK_3i.js";const d=JSON.parse('{"title":"直播回放 | AI能写量化交易，为什么90%的人实盘不赚钱？","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. 核心方法论","slug":"_1-核心方法论","link":"#_1-核心方法论","children":[{"level":3,"title":"1.1 AI 加速的四个轨道 + 人的判断门","slug":"_1-1-ai-加速的四个轨道-人的判断门","link":"#_1-1-ai-加速的四个轨道-人的判断门","children":[]},{"level":3,"title":"1.2 如何判断一条 AI 策略是否值得相信","slug":"_1-2-如何判断一条-ai-策略是否值得相信","link":"#_1-2-如何判断一条-ai-策略是否值得相信","children":[]},{"level":3,"title":"1.3 信号 vs 成交：A 点的 gap 故事","slug":"_1-3-信号-vs-成交-a-点的-gap-故事","link":"#_1-3-信号-vs-成交-a-点的-gap-故事","children":[]},{"level":3,"title":"1.4 过拟合：样本内冠军没有价值","slug":"_1-4-过拟合-样本内冠军没有价值","link":"#_1-4-过拟合-样本内冠军没有价值","children":[]},{"level":3,"title":"1.5 六条证据链：正反向追溯","slug":"_1-5-六条证据链-正反向追溯","link":"#_1-5-六条证据链-正反向追溯","children":[]},{"level":3,"title":"1.6 合格的结论 = 结论 + 证据 + 边界","slug":"_1-6-合格的结论-结论-证据-边界","link":"#_1-6-合格的结论-结论-证据-边界","children":[]},{"level":3,"title":"1.7 程序必须回答两件事","slug":"_1-7-程序必须回答两件事","link":"#_1-7-程序必须回答两件事","children":[]}]},{"level":2,"title":"2. 策略回测的纪律","slug":"_2-策略回测的纪律","link":"#_2-策略回测的纪律","children":[]},{"level":2,"title":"3. 课程设计","slug":"_3-课程设计","link":"#_3-课程设计","children":[]},{"level":2,"title":"4. 课程定位","slug":"_4-课程定位","link":"#_4-课程定位","children":[]},{"level":2,"title":"5. 交付成果","slug":"_5-交付成果","link":"#_5-交付成果","children":[]}],"relativePath":"Codex与LLM量化交易实战课/直播回放｜AI能写量化交易，为什么90％的人实盘不赚钱？.md","filePath":"Codex与LLM量化交易实战课/直播回放｜AI能写量化交易，为什么90％的人实盘不赚钱？.md","lastUpdated":null}'),t={name:"Codex与LLM量化交易实战课/直播回放｜AI能写量化交易，为什么90％的人实盘不赚钱？.md"};function n(r,l,s,u,_,o){return p(),a("div",null,[...l[0]||(l[0]=[e(`<h1 id="直播回放-ai能写量化交易-为什么90-的人实盘不赚钱" tabindex="-1">直播回放 | AI能写量化交易，为什么90%的人实盘不赚钱？ <a class="header-anchor" href="#直播回放-ai能写量化交易-为什么90-的人实盘不赚钱" aria-label="Permalink to &quot;直播回放 | AI能写量化交易，为什么90%的人实盘不赚钱？&quot;">​</a></h1><p>你好，我是袁从德，欢迎来到《Codex 与 LLM 量化交易实战课》。今天我们不只是讨论怎么去选股、什么股票会涨，我们更多地会去讨论为什么 AI 能写交易策略，回测结果也很漂亮，但仍然不可信。我们通过现场拆解同一条三七均线策略，从「看起来有效」走到「可复查」的整个正确链。整个课程的最终交付是一个可运行、可复查的 AI 量化研究系统。</p><h2 id="_1-核心方法论" tabindex="-1">1. 核心方法论 <a class="header-anchor" href="#_1-核心方法论" aria-label="Permalink to &quot;1. 核心方法论&quot;">​</a></h2><h3 id="_1-1-ai-加速的四个轨道-人的判断门" tabindex="-1">1.1 AI 加速的四个轨道 + 人的判断门 <a class="header-anchor" href="#_1-1-ai-加速的四个轨道-人的判断门" aria-label="Permalink to &quot;1.1 AI 加速的四个轨道 + 人的判断门&quot;">​</a></h3><p>现在 AI 相比前几年更智能了，可以写代码、做日常办公。但 AI 虽然很智能，不等于会做判断。在整个量化过程中，AI 加速的四个轨道是：</p><ul><li>AI 做什么</li></ul><p>轨道</p><ul><li>人要判断什么不判断会怎样</li></ul><ol><li>研究假设</li></ol><ul><li>规划规则原型原型是否可证伪不可证伪的策略无法验证</li></ul><ol start="2"><li>可信数据</li></ol><ul><li>清洗特征数据时间、版本是否符合预期错误时间会丢失未来信息</li></ul><ol start="3"><li>策略验证</li></ol><ul><li>写代码 + 报告扭曲 K 线，行业被重度扭曲成本与风险</li></ul><ol start="4"><li>结论发布</li></ol><ul><li>生成页面 / 文档复算和追溯结论无法验证</li></ul><p>大模型去辅助量化有一个大问题，它虽然极大提升了效率，但结论不一定是置信的。只有通过设置的判断门全部通过，AI 产出才有资格进入发布流程。AI 可以提高实验速度，但决策还是要人去决策，数据、假设、风险自始至终都还是由人来承担的。</p><h3 id="_1-2-如何判断一条-ai-策略是否值得相信" tabindex="-1">1.2 如何判断一条 AI 策略是否值得相信 <a class="header-anchor" href="#_1-2-如何判断一条-ai-策略是否值得相信" aria-label="Permalink to &quot;1.2 如何判断一条 AI 策略是否值得相信&quot;">​</a></h3><p>我们用大模型写策略时，代码能跑、信号清楚、曲线非常漂亮。但同一套策略信号在不同位置必须是一个可复查的状态，这时候我们必须问：这条策略是可信的吗？</p><p>五道门（缺一不可）：</p><ul><li><p>数据可复现门：每条数据的来源、字段、版本是否可复现？</p></li><li><p>信号时间门：信号时间、成交与观测信息是否成立？</p></li><li><p>参数搜索透明门：拒绝脑补，如果搜索路径不透明，稍微一个扰动就不可回溯，数据不可用。</p></li><li><p>成本门：不光看收益，还要把手续费、罚点、成交摩擦都算进来。</p></li><li><p>风险门：仓位、止损、回撤纪律要明确。不建议一次性打光子弹，必须留有足够子弹。</p></li></ul><p>关于成本：量化交易里，一次交易可能一个点都不到收益。但是 Web3 场景有罚点和成交手续费，非常高。每次交易时，不光要看当前收益，还要看罚点和成交是不是也要放进一起算作成本。</p><p>关于纪律：整个交易过程中，回撤和止损的纪律一定要严明。这也是用程序化交易的一个比较好的方式：人会带来很多主观和情绪波动，很难严格执行。</p><h3 id="_1-3-信号-vs-成交-a-点的-gap-故事" tabindex="-1">1.3 信号 vs 成交：A 点的 gap 故事 <a class="header-anchor" href="#_1-3-信号-vs-成交-a-点的-gap-故事" aria-label="Permalink to &quot;1.3 信号 vs 成交：A 点的 gap 故事&quot;">​</a></h3><p>我们看到同一条 K 线收盘的成交价，可能是当时上不去的。比如我们在 A 点买入，市场价格波动，A 点不一定能真实买得进去；C 点想卖，C 点挂单之后不一定能成交。理想决策和现实反馈其实是有 gap 的。</p><p>硬规则：</p><ul><li><p>信号产生后，成交才能发生，否则回测结果作废。我们不可能信号没产生就成交了。</p></li><li><p>日志里必须保留“成交 + 拒绝”两类记录。如果只有成交日志，整个交易数据都是“粉饰”的，回测结果是有偏的。</p></li></ul><p>关键原则（时间顺序不可倒置）：</p><ul><li>一定是「信号 → 订单 → 成交」，不可能从成交倒推信号。这是不合理的。</li></ul><h3 id="_1-4-过拟合-样本内冠军没有价值" tabindex="-1">1.4 过拟合：样本内冠军没有价值 <a class="header-anchor" href="#_1-4-过拟合-样本内冠军没有价值" aria-label="Permalink to &quot;1.4 过拟合：样本内冠军没有价值&quot;">​</a></h3><p>做策略时很容易过拟合。大部分情况下我们都在“眼盲”，只关注了比较好的样本。</p><p>单样本内冠军的陷阱：</p><p>维度</p><ul><li><p>现象风险</p></li><li><p>单边市场下做多 / 做空</p></li></ul><p>特定场景</p><ul><li>震荡市就会失效</li></ul><p>特定时间</p><ul><li>某段行情特别好行情轮动后失效</li></ul><p>特定曲线</p><ul><li>单一参数特别好附近参数很差</li></ul><p>很多情况下“我的策略非常好”，其实是因为样本回溯过程就有问题，前期没发现而已。</p><p>正确做法：</p><ul><li><p>样本内可能数据亮眼，样本外可能就负收益了</p></li><li><p>滚动验证：不停向前滚动训练与验证</p></li><li><p>看三道门是否同时通过，不是看整个收益为正</p></li><li><p>离线失败不是坏事——没上线就没亏钱，及早发现，及早停止</p></li></ul><h3 id="_1-5-六条证据链-正反向追溯" tabindex="-1">1.5 六条证据链：正反向追溯 <a class="header-anchor" href="#_1-5-六条证据链-正反向追溯" aria-label="Permalink to &quot;1.5 六条证据链：正反向追溯&quot;">​</a></h3><p>一条可信的结论，必须沿着六条证据链进行正反向追溯。</p><p>正向研究流程：</p><ul><li><p>基于当前市场做假设：假设必须可证伪、可停止</p></li><li><p>收集数据：来源、时间、版本要清楚</p></li><li><p>生成信号：信号要有依据、时效性</p></li><li><p>回测：关注事件发展顺序、成交量、罚点</p></li><li><p>评估三件事：是否能带来正向收益、风险如何（夏普 / 下补率）、回测稳定性</p></li><li><p>交付：完整的日志链，可实时追溯</p></li></ul><p>四层正向追溯链：所有的输入数据都要有来源和快照；信号依据要有证据；成交记录要记录是否成交和是否被拒绝；评估结果不光要看收益，还要看风险。</p><p>核心反推：任何结论都必须沿着交付逐层返回追溯输入，所有东西都是可以回溯的。从交互回溯到评估，评估回溯到回测，这样整个结论研究过程就是相对稳定的。</p><h3 id="_1-6-合格的结论-结论-证据-边界" tabindex="-1">1.6 合格的结论 = 结论 + 证据 + 边界 <a class="header-anchor" href="#_1-6-合格的结论-结论-证据-边界" aria-label="Permalink to &quot;1.6 合格的结论 = 结论 + 证据 + 边界&quot;">​</a></h3><p>层级</p><ul><li><p>要求</p></li><li><p>明确买入 / 卖出 / 观望，不能模棱两可。可能买入、可能不买入，毫无价值</p></li></ul><p>结论层</p><p>证据层</p><ul><li>判断依据、观测时间、信息来源，三条都要有</li></ul><p>边界层</p><ul><li>风险因素、策略失效条件，要清晰可判断</li></ul><p>置信度原则：一定要有置信程度的衡量。证据不足时，策略核心结论一定偏中性，或拒绝判断，不能在条件不成熟时还给予肯定判断。</p><h3 id="_1-7-程序必须回答两件事" tabindex="-1">1.7 程序必须回答两件事 <a class="header-anchor" href="#_1-7-程序必须回答两件事" aria-label="Permalink to &quot;1.7 程序必须回答两件事&quot;">​</a></h3><p>为什么成交、为什么拒绝，这两个行为必须记录清楚。如果只有成交与拒绝两个行为，但中间过程是缺失的，对策略的可靠性是相对缺失的，对后续迭代也是相对缺失的。所有的市场分类行为，尽最大能力去收集，把它快照下来。</p><h2 id="_2-策略回测的纪律" tabindex="-1">2. 策略回测的纪律 <a class="header-anchor" href="#_2-策略回测的纪律" aria-label="Permalink to &quot;2. 策略回测的纪律&quot;">​</a></h2><p>回测的核心理念：策略回测不是凭空捏造，而是依赖于市场动态变化做相应处理。</p><p>回测核心循环：</p><ul><li><p>行情到达：当前可见的价格和时间</p></li><li><p>生成信号：这一刻已知的信息</p></li><li><p>风险检查：仓位限制优先于成交</p></li><li><p>模拟成交：可成交性 + 成本</p></li><li><p>更新状态：权益、持仓、日志</p></li><li><p>循环：一直积累日志</p></li></ul><p>核心就是：市场发生了什么，系统需要记录并处理什么。 市场就是一个快照。</p><h2 id="_3-课程设计" tabindex="-1">3. 课程设计 <a class="header-anchor" href="#_3-课程设计" aria-label="Permalink to &quot;3. 课程设计&quot;">​</a></h2><p>整套 AI 量化交易系统的项目结构如下（统一项目下进行）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>行情 → 信号 → 策略 → 回测 → 风控 → 网页端</span></span>
<span class="line"><span> ↑                                ↓</span></span>
<span class="line"><span> └── 市场总览、市场情报、计费雷达 ←─┘</span></span></code></pre></div><p>关键模块：</p><ul><li><p>市场总览：在市场上找机会</p></li><li><p>策略 + 回测：验证想法</p></li><li><p>模拟交易：仿真环境</p></li><li><p>数据源追踪：完整的数据可追溯</p></li><li><p>风控：做风控，再做交易</p></li><li><p>市场情报：动态追踪不同币种的计费点</p></li></ul><p>值得强调：如果不能保证本金不亏空，所有的策略都毫无价值了。任何一次失败，都可能血本无归。</p><p>35 讲的章节结构：</p><p>我们整个 35 讲其实是完成一套可运行、可复查的研究系统。</p><ul><li><p>明确研究边界（假设与验收标准）</p></li><li><p>数据可信（明确快照和来源）</p></li><li><p>数据结构化（怎么去做证据与失效样本）</p></li><li><p>事件回测（提供回测引擎和成交日志）</p></li><li><p>评估</p></li><li><p>Web 系统 + 自动化交易平台</p></li></ul><h2 id="_4-课程定位" tabindex="-1">4. 课程定位 <a class="header-anchor" href="#_4-课程定位" aria-label="Permalink to &quot;4. 课程定位&quot;">​</a></h2><p>适合加入的人：</p><ul><li><p>愿意亲自运行和复算代码</p></li><li><p>愿意核对数据假设和证据</p></li><li><p>接受课程不提供买卖点位</p></li><li><p>愿意处理数据、洞察数据、挖掘因子</p></li><li><p>拿到结论时，愿意分析、补齐证据、或用数据增强结论</p></li></ul><p>不适合加入的人：</p><ul><li><p>期望课程能找到一条稳定正收益的策略（不可能，即使是挣钱的策略也会随行情、流动性而失效）</p></li><li><p>期望课程承诺收益（不承诺收益，只要求一起完成一套可复查的研究流程）</p></li><li><p>不愿意处理数据（大部分时间都在挖掘因子）</p></li></ul><p>判断标准就是：拿到一条结论时，你是不是愿意去分析它，补齐各种证据去支撑这个结论。从复制策略走向独立完成研究，如果能走到这一步，学习就算成功了。</p><h2 id="_5-交付成果" tabindex="-1">5. 交付成果 <a class="header-anchor" href="#_5-交付成果" aria-label="Permalink to &quot;5. 交付成果&quot;">​</a></h2><p>课程交付的不只是一套代码（不过代码确实很全），更多的是可持续迭代的工作流、方法论、经验。</p><p>6 项关键交付：</p><ul><li><p>代码可运行：整套研究系统能跑起来</p></li><li><p>可复算：固定快照和关键结果做复算</p></li><li><p>可解释：每个信号的依据、成本、失效都能做出自己的解释（抄不到也学不到）</p></li><li><p>可交付：页面报告 + 经验包</p></li><li><p>可持续迭代：工作流而非一次性代码</p></li><li><p>行业认知 ：对量化过程有体系化的认知，风险点在哪里、到底是怎么运行的</p></li></ul><p>本场直播的主要内容就到这里，如果有兴趣深度了解 AI 量化交易，欢迎到专栏正文中学习！</p>`,85)])])}const c=i(t,[["render",n]]);export{d as __pageData,c as default};
